import{_ as i,a,c as t,b as s}from"./chunks/framework.b9WMfGr4.js";const u=JSON.parse('{"title":"04-WSL配置技巧","description":"","frontmatter":{"title":"04-WSL配置技巧","create-time":"2026-05-14T00:00:00.000Z","update-time":"2026-05-14T00:00:00.000Z"},"headers":[],"relativePath":"posts/开发经验/环境与工具/04-WSL配置技巧.md","filePath":"posts/开发经验/环境与工具/04-WSL配置技巧.md"}'),n={name:"posts/开发经验/环境与工具/04-WSL配置技巧.md"};function o(l,e,r,d,p,h){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h2 id="在-windows-中通过-wsl-使用-ubuntu" tabindex="-1">在 Windows 中通过 WSL 使用 Ubuntu <a class="header-anchor" href="#在-windows-中通过-wsl-使用-ubuntu" aria-label="Permalink to &quot;在 Windows 中通过 WSL 使用 Ubuntu&quot;">​</a></h2><h3 id="快速启动-ubuntu-终端" tabindex="-1">快速启动 Ubuntu 终端 <a class="header-anchor" href="#快速启动-ubuntu-终端" aria-label="Permalink to &quot;快速启动 Ubuntu 终端&quot;">​</a></h3><ol><li>将 Ubuntu 设置为默认的终端</li></ol><p><img src="https://gitee.com/Seniorsy/pic-go/raw/master/typora/image-20260514195128427.png" alt="image-20260514195128427" referrerpolicy="no-referrer" loading="lazy"></p><ol start="2"><li>使用快捷指令打开： <code>win+R</code> 启动快捷启动程序，然后输入 <code>wt</code> （windows terminal 猜的简写），打开默认终端，即可通过快捷键启动 Ubuntu 终端系统</li></ol><h3 id="使用经验" tabindex="-1">使用经验 <a class="header-anchor" href="#使用经验" aria-label="Permalink to &quot;使用经验&quot;">​</a></h3><h4 id="ubuntu-访问-windows-中的文件路径" tabindex="-1">Ubuntu 访问 Windows 中的文件路径 <a class="header-anchor" href="#ubuntu-访问-windows-中的文件路径" aria-label="Permalink to &quot;Ubuntu 访问 Windows 中的文件路径&quot;">​</a></h4><p>Ubuntu 访问 Windows 的文件路径的时候，需要加上文件路径前缀 <code>/mnt/</code> ，并且盘符变成了目录路径，盘符为小写。</p><p>例如：<code>/mnt/c/users/</code></p><h4 id="在-ubuntu-中通过指令打开-windows-文件管理器" tabindex="-1">在 Ubuntu 中通过指令打开 Windows 文件管理器 <a class="header-anchor" href="#在-ubuntu-中通过指令打开-windows-文件管理器" aria-label="Permalink to &quot;在 Ubuntu 中通过指令打开 Windows 文件管理器&quot;">​</a></h4><p>在命令行终端中，执行 <code>explorer.exe .</code> 可以打开以当前文件路径为基准的 Windows 文件管理器。</p><p><img src="https://gitee.com/Seniorsy/pic-go/raw/master/typora/image-20260514195753517.png" alt="image-20260514195753517" referrerpolicy="no-referrer" loading="lazy"></p><h3 id="多任务分屏操作" tabindex="-1">多任务分屏操作 <a class="header-anchor" href="#多任务分屏操作" aria-label="Permalink to &quot;多任务分屏操作&quot;">​</a></h3><ul><li><p>垂直分屏：<code>Alt + Shift + =</code></p></li><li><p>水平分屏：<code>Alt + Shift + -</code></p></li><li><p>关闭当前窗格：<code>Ctrl + Shift + W</code></p></li><li><p>使用 <code>Alt</code> + <code>上下左右</code> 进行切换窗口</p></li></ul><h3 id="界面缩放" tabindex="-1">界面缩放 <a class="header-anchor" href="#界面缩放" aria-label="Permalink to &quot;界面缩放&quot;">​</a></h3><p>指令：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">Ctrl</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> &#39;+&#39;</span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">   # 放大</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">Ctrl</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> &#39;-&#39;</span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">   # 缩小</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div>`,17)])])}const k=i(n,[["render",o]]);export{u as __pageData,k as default};
